'use strict';
// Keep one decoded avatar node across locks. Never paint a placeholder and swap it later.
let entryIdentityPrepared=null,entryIdentityKey='',entryIdentityWaiters=[],entryExit=null,entryFaceStart=null;
const entryBootstrap=(()=>{try{return JSON.parse(document.getElementById('entry-bootstrap')?.textContent||'null')}catch{return null}})();
function identitySignature(value){return value?String(value.length)+':'+value.slice(0,64)+':'+value.slice(-64):''}
function currentEntryIdentity(){const signature=identitySignature(state.avatar||'');return {name:state.name,avatar:signature&&signature===entryBootstrap?.avatarSignature?entryBootstrap.avatar:(state.avatar||null),avatarSignature:signature}}
function preparedIdentity(info){const key=String(info.avatarSignature||identitySignature(info.avatar||''))+'|'+String(info.name||'');if(entryIdentityPrepared&&key===entryIdentityKey)return entryIdentityPrepared;entryIdentityKey=key;entryIdentityPrepared=(async()=>{let node=null;if(info.avatar){const image=new Image();image.decoding='sync';image.loading='eager';image.alt='Фото профілю';image.src=info.avatar;if(!image.complete||!image.naturalWidth)await image.decode().catch(()=>{});if(image.naturalWidth)node=image}return {name:info.name||'',avatar:info.avatar||null,node}})();return entryIdentityPrepared}
function cacheEntryIdentity(){if(loading)return;const info=currentEntryIdentity();try{localStorage.setItem('entry-identity-cache',JSON.stringify(info))}catch{}const ready=preparedIdentity(info);for(const resolve of entryIdentityWaiters.splice(0))resolve(ready)}
function entryIdentity(){if(!loading)return preparedIdentity(currentEntryIdentity());if(entryBootstrap)return preparedIdentity(entryBootstrap);try{const cached=JSON.parse(localStorage.getItem('entry-identity-cache')||'null');if(cached?.avatar)return preparedIdentity(cached)}catch{}return new Promise(resolve=>entryIdentityWaiters.push(resolve))}
function closeFaceAlert(layer){clearTimeout(entryScanTimer);clearTimeout(entryFaceStart);entryScanTimer=null;entryFaceStart=null;layer?.querySelector('.native-auth-scrim')?.remove();layer?.querySelector('.native-auth-alert')?.remove();layer?.classList.remove('native-face-active');if(layer)layer.dataset.faceCancelled='true'}
function startFaceAlert(layer,force=false){if(!layer?.isConnected||layer.dataset.ready!=='true'||document.visibilityState!=='visible'||(entryScanTimer&&!force))return;closeFaceAlert(layer);layer.dataset.faceCancelled='false';layer.classList.add('native-face-active');layer.insertAdjacentHTML('beforeend',`<div class="native-auth-scrim"></div><div class="native-auth-alert" role="status" aria-label="Face ID · демонстраційна анімація"><div class="native-auth-body"><span class="native-recorded-orb" aria-hidden="true"></span><strong>Face ID</strong><small>Ще раз</small></div><button type="button" class="native-auth-retry">Ще раз Face ID</button><button type="button" class="native-auth-cancel">Скасувати</button></div>`);layer.querySelector('.native-auth-retry').onclick=()=>startFaceAlert(layer,true);layer.querySelector('.native-auth-cancel').onclick=()=>closeFaceAlert(layer);entryScanTimer=setTimeout(()=>{entryScanTimer=null;unlockNativeEntry()},1100)}
const unlockBeforeSoftEntry=unlockNativeEntry;
unlockNativeEntry=function(){const layer=$('.entry-overlay');if(!layer||entryExit)return;clearTimeout(entryScanTimer);clearTimeout(entryFaceStart);entryScanTimer=null;entryFaceStart=null;const duration=shouldReduceMotion()?140:240,app=$('#app'),nav=$('#nav');const appMotion=app.animate(shouldReduceMotion()?[{opacity:.8},{opacity:1}]:[{opacity:.75,filter:'blur(4px)'},{opacity:1,filter:'blur(0px)'}],{duration,easing:'cubic-bezier(.23,1,.32,1)',fill:'both'});const navMotion=nav.animate([{opacity:.7},{opacity:1}],{duration,easing:'cubic-bezier(.23,1,.32,1)',fill:'both'});const motion=layer.animate([{opacity:1},{opacity:0}],{duration,easing:'cubic-bezier(.23,1,.32,1)',fill:'both'});const exit={layer,motion,appMotion,navMotion};entryExit=exit;motion.finished.then(()=>{if(entryExit!==exit)return;unlockBeforeSoftEntry();appMotion.cancel();navMotion.cancel();entryExit=null}).catch(()=>{})};
pressNativePin=function(value){const layer=$('.entry-native');if(!layer||layer.querySelector('.native-auth-alert')||entryExit||layer.dataset.ready!=='true')return;clearTimeout(entryFaceStart);entryFaceStart=null;clearTimeout(nativePinReset);nativePinReset=null;layer.dataset.faceCancelled='true';if(value==='delete')nativePin=nativePin.slice(0,-1);else if(/^\d$/.test(value)){if(nativePin.length===4)nativePin='';nativePin+=value}updateNativeDots();if(nativePin.length===4){if(nativePin===localStorage.getItem('demo-pin'))unlockNativeEntry();else{updateNativeDots(true);nativePinReset=setTimeout(()=>{nativePin='';updateNativeDots()},500)}}};
function vocativeEntryName(name){const first=String(name||'').trim().split(' ')[0];return ({'Олег':'Олеже','Олександр':'Олександре','Тарас':'Тарасе','Андрій':'Андрію','Богдан':'Богдане','Костянтин':'Костянтине'})[first]||first}
showEntry=function(){if(adminMode)return;if($('#modal')?.open)$('#modal').close();if(entryExit){const exit=entryExit;entryExit=null;exit.motion.cancel();exit.appMotion.cancel();exit.navMotion.cancel();exit.layer.style.opacity='1'}let layer=$('.entry-overlay');if(layer&&!layer.classList.contains('faithful-entry')){layer.remove();layer=null}const autoFace=localStorage.getItem('demo-face')==='1';if(!layer){nativePin='';layer=document.createElement('div');layer.className='entry-overlay entry-native faithful-entry preparing-entry';layer.dataset.ready='false';layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');layer.setAttribute('aria-label','Вхід у демонстраційний застосунок');layer.innerHTML=`<div class="native-entry-identity"><span class="native-entry-avatar"></span><h1></h1><p class="native-pin-instruction" aria-live="polite">Уведіть ПІН-код</p><div class="native-pin-dots" aria-label="Чотири цифри ПІН-коду"><i></i><i></i><i></i><i></i></div></div><div class="native-entry-keypad">${['1','2','3','4','5','6','7','8','9','face','0','delete'].map(value=>`<button type="button" class="native-key ${/\d/.test(value)?'number-key':''}" data-pin-key="${value}" aria-label="${value==='delete'?'Видалити цифру':value==='face'?'Face ID':value}">${value==='face'?faceMarkup:value==='delete'?'<svg viewBox="0 0 32 24" aria-hidden="true"><path d="M10 3H28v18H10L2 12Z" fill="currentColor"/><path d="m16 8 8 8m0-8-8 8" stroke="#222" stroke-width="1.5"/></svg>':value}</button>`).join('')}</div><button class="native-forgot-pin">Забули ПІН-код?</button>`;document.body.append(layer);$('#app').inert=true;$('#nav').inert=true;layer.querySelectorAll('[data-pin-key]').forEach(button=>button.onclick=()=>button.dataset.pinKey==='face'?startFaceAlert(layer,true):pressNativePin(button.dataset.pinKey));layer.querySelector('.native-forgot-pin').onclick=()=>inform('Забули ПІН-код?','Це демонстраційний PIN, заданий вами у налаштуваннях цього пристрою.');const activeLayer=layer;entryIdentity().then(info=>{if(!activeLayer.isConnected)return;const avatar=activeLayer.querySelector('.native-entry-avatar');if(info.node)avatar.replaceChildren(info.node);else avatar.innerHTML=icon('cat-fill');activeLayer.querySelector('h1').textContent='З поверненням'+(info.name?', '+vocativeEntryName(info.name):'')+'!';activeLayer.dataset.ready='true';activeLayer.classList.remove('preparing-entry');if(autoFace&&document.visibilityState==='visible')entryFaceStart=setTimeout(()=>{entryFaceStart=null;startFaceAlert(activeLayer)},100)})}else if(document.visibilityState==='hidden'){closeFaceAlert(layer);layer.dataset.faceCancelled='false'}else if(autoFace&&layer.dataset.ready==='true'&&layer.dataset.faceCancelled!=='true'&&!entryScanTimer&&!entryFaceStart){entryFaceStart=setTimeout(()=>{entryFaceStart=null;startFaceAlert(layer)},60)}};
const renderBeforeIdentityCache=render;render=function(){renderBeforeIdentityCache();cacheEntryIdentity()};
clearTimeout(entryScanTimer);clearTimeout(entryFaceStart);entryScanTimer=null;entryFaceStart=null;const entryWasVisible=!!$('.entry-overlay');$('.entry-overlay')?.remove();cacheEntryIdentity();if(entryWasVisible)showEntry();actions['lock-demo']=()=>showEntry();
